  }).value;

  const issued = issueInvoice(invoice, []).value;
  const r = vatSummary([issued]);

  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 0);
  assert.equal(r[0].base, 95000);
  assert.equal(r[0].vat, 0);
});

test('vatSummary VAT calculation with rounding', () => {
  const invoice = {
    status: 'issued',
    lines: [
      { qty: 1, unitPrice: 100, vatRate: 21 },
      { qty: 1, unitPrice: 50, vatRate: 21 },
    ],
  };

  const r = vatSummary([invoice]);

  // Base: 100 + 50 = 150
  // VAT per line: 100 * 0.21 = 21, 50 * 0.21 = 10.5 -> 10 (banker's rounding)
  // Total VAT: 21 + 10 = 31
  assert.equal(r[0].base, 150);
  assert.equal(r[0].vat, 31);
});

test('vatSummary with mixed paid and partially_paid', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const paid = recordPayment(issued1, { amount: 10285, date: '2026-10-05' }).value;
  const partial = recordPayment(issued2, { amount: 5000, date: '2026-10-05' }).value;

  const r = vatSummary([paid, partial]);

  // Both invoices have same items: base 8500 + 17000, vat = 1785 + 3570
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 25500);
  assert.equal(r[0].vat, 5355);
});

test('vatSummary handles edge case with 0 discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const r = vatSummary([issued]);

  assert.equal(r.length, 1);
  // With 0% discount, base should equal line total
  assert.equal(r[0].base, 17000);
  assert.equal(r[0].vat, 3570);
});

test('vatSummary accumulates across multiple invoices and rates', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 50 },
    ],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const r = vatSummary([issued1, issued2]);

  assert.equal(r.length, 2);
  // 21% VAT: 8500 + 8500 + 17000 = 34000, VAT = 7140
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 34000);
  assert.equal(r[0].vat, 7140);
  // 9% VAT: 1850, VAT = 166
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 1850);
  assert.equal(r[1].vat, 166);
});

